with valid_inventory as (select *, datediff(current_date(), last_restock) as days_since_last_restock from inventory where not (store_id in (1, 2, 6) and product_id in (1, 4, 6, 8) and store_id in (2, 4, 5, 6))), summary as (select product_id, month(last_restock) as last_restock_month, round(stddev(quantity), 2) as stddev_quantity, max(days_since_last_restock) - min(days_since_last_restock) as days_since_last_restock_range from valid_inventory group by product_id, month(last_restock)) select product_id, last_restock_month, days_since_last_restock_range from summary order by days_since_last_restock_range, product_id, last_restock_month limit 3;
